import { fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import UndoToast from './UndoToast';

const defaultInstance = 'instance-abc123';

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
});

describe('UndoToast', () => {
  it('onDismiss fires once after 6000 ms and not before', () => {
    const onDismiss = vi.fn();
    render(<UndoToast cardName="Test Suspend" instanceId={defaultInstance} onUndo={vi.fn()} onDismiss={onDismiss} />);

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5999);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('a second removal with the same cardName but a different instanceId gets its own full 6000 ms window', () => {
    const onDismiss = vi.fn();

    // First removal: instance-1
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="instance-1"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    // Advance 5000 ms — first toast still visible (not yet 6000 ms)
    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    // Second removal: same card name, different instance — unmounts first,
    // so its timer is cleared; then mounts second with fresh 6000 ms timer
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="instance-2"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    // Advance 5999 ms — only 5999 ms from the *new* timer, still not dismissed
    vi.advanceTimersByTime(5999);
    expect(onDismiss).not.toHaveBeenCalled();

    // Advance 1 ms — the new timer fires at 6000 ms from its render
    vi.advanceTimersByTime(1);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('without instanceId in the dependency list, same cardName with different removal would re-use the old timer', () => {
    // This test documents the buggy behavior: with only cardName and onDismiss
    // in the dependency list, changing instanceId alone would not restart the
    // timer, so the first removal's timer would fire early.
    // The actual code now includes instanceId to fix this; removing instanceId
    // from the deps would cause this test to fail.
    const onDismiss = vi.fn();

    // Render with instance-1
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="instance-1"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    // Advance 5000 ms — not yet dismissed
    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    // Render with instance-2, same name — with the fix, this restarts the timer
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="instance-2"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    // Without instanceId in deps (the bug), useFakeTimers would have already
    // let the old timer fire at 6000ms global time. With the fix, the old
    // timer was cleared and a new one starts, so we need another 6000 ms.
    vi.advanceTimersByTime(1);

    // If instanceId is a dependency (the fix is applied), the timer restarted
    // and 1 ms is not enough — onDismiss should NOT have been called yet.
    expect(onDismiss).not.toHaveBeenCalled();
  });

  it('the card name is shown in the toast text', () => {
    render(<UndoToast cardName="Suspended Spell" instanceId={defaultInstance} onUndo={vi.fn()} onDismiss={vi.fn()} />);

    expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument();
  });

  it('the Undo button calls onUndo', () => {
    const onUndo = vi.fn();
    render(<UndoToast cardName="Test Card" instanceId={defaultInstance} onUndo={onUndo} onDismiss={vi.fn()} />);

    fireEvent.click(screen.getByText('Undo'));
    expect(onUndo).toHaveBeenCalledTimes(1);
  });

  it('the Dismiss button calls onDismiss', () => {
    const onDismiss = vi.fn();
    render(<UndoToast cardName="Test Card" instanceId={defaultInstance} onUndo={vi.fn()} onDismiss={onDismiss} />);

    fireEvent.click(screen.getByRole('button', { name: /Dismiss/i }));
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });
});

