it('a second removal with the same cardName but a different instanceId gets its own full 6000 ms window', () => {
  const onDismiss = vi.fn();

  // First removal: instance-1, timer scheduled at t=6000
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  expect(onDismiss).not.toHaveBeenCalled();

  // Advance 5500 ms — first toast still visible (timer fires at 6000)
  vi.advanceTimersByTime(5500);
  expect(onDismiss).not.toHaveBeenCalled();

  // Second removal: same card name, different instance
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-2"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // Without the fix, the old timer fires at t=6000 (500 ms from now).
  // With the fix, the old timer was cleared and a fresh one starts at
  // t=5500+6000=11500.  At t=6500 we should not see a call with the fix.
  vi.advanceTimersByTime(1000);
  expect(onDismiss).not.toHaveBeenCalled();

  // But now 6000 ms have passed from the SECOND render, so it should fire:
  expect(onDismiss).toHaveBeenCalledTimes(1);
});

