it('a second removal with the same cardName but a different instanceId gets its own full 6000 ms window', () => {
  const onDismiss = vi.fn();

  // First removal: instance-1
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  expect(onDismiss).not.toHaveBeenCalled();

  // Wait for the full 6000 ms window of the first removal
  vi.advanceTimersByTime(6000);
  // The first toast should fire
  expect(onDismiss).toHaveBeenCalledTimes(1);

  // Reset and simulate the actual bug scenario:
  // First removal: instance-1
  vi.mocked(onDismiss).mockClear();
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // Advance 5000 ms (less than full window)
  vi.advanceTimersByTime(5000);
  expect(onDismiss).not.toHaveBeenCalled();

  // RERENDER with different instance but same cardName — this is the critical
  // step. The effect should re-run and start a fresh 6000 ms timer.
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-2"
