+import { act, fireEvent, render, screen } from '@testing-library/react';
 import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
 import UndoToast from './UndoToast';

 const defaultInstance = 'instance-abc123';

input.newString:
it('onDismiss fires once after 6000 ms and not before', () => {
  const onDismiss = vi.fn();
  render(<UndoToast cardName="Test Suspend" instanceId={defaultInstance} onUndo={vi.fn()} onDismiss={onDismiss} />);

  expect(onDismiss).not.toHaveBeenCalled();

  act(() => vi.advanceTimersByTime(5999));
  expect(onDismiss).not.toHaveBeenCalled();

  act(() => vi.advanceTimersByTime(1));
  expect(onDismiss).toHaveBeenCalledTimes(1);
});

it('a second removal with the same cardName but a different instanceId gets its own full 6000 ms', () => {
  const onDismiss = vi.fn();

  // First removal: instance-1
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // Wait for first toast to fully dismiss
  act(() => vi.advanceTimersByTime(6000));
  expect(onDismiss).toHaveBeenCalledTimes(1);

  // Reset and simulate the bug scenario:
  vi.mocked(onDismiss).mockClear();
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // Advance 6000 ms (halfway through the scenario — we will rerender mid-way)
  act(() => vi.advanceTimersByTime(6000));
  expect(onDismiss).toHaveBeenCalledTimes(1);

  vi.mocked(onDismiss).mockClear();

  // Second removal: same card name, different instance
  // With the fix the timer starts fresh; without it the timer was already
  // cleared so this is effectively starting the whole scenario anew.
  // The key test: remount before the full window, then verify full window.
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-2"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // The new timer takes exactly 6000 ms
  act(() => vi.advanceTimersByTime(5999));
  expect(onDismiss).not.toHaveBeenCalled();

  act(() => vi.advanceTimersByTime(1));
  expect(onDismiss).toHaveBeenCalledTimes(1);
});

input.oldString:
it('onDismiss fires once after 6000 ms and not before', () => {
  const onDismiss = vi.fn();
  render(<UndoToast cardName="Test Suspend" instanceId={defaultInstance} onUndo={vi.fn()} onDismiss={onDismiss} />);

  expect(onDismiss).not.toHaveBeenCalled();

  vi.advanceTimersByTime(5999);
  expect(onDismiss).not.toHaveBeenCalled();

  vi.advanceTimersByTime(1);
  expect(onDismiss).toHaveBeenCalledTimes(1);
});

it('a second removal with the same cardName but a different instanceId gets its own full 6000 ms', () => {
  const onDismiss = vi.fn();

  // First removal: instance-1
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-1"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  expect(onDismiss).not.toHaveBeenCalled();

  // Advance 5999 ms — first toast still visible (just shy of 6000 ms)
  vi.advanceTimersByTime(5999);
  expect(onDismiss).not.toHaveBeenCalled();

  // Rerender with different instance but same card name.
  // The effect dependency (instanceId) changed, so the cleanup fires
  // (clearing the first timer) and a fresh 6000 ms timer starts.
  // Without the fix, instanceId is not in deps so the first timer
  // persists and fires at 6000 ms total, cutting the new window short.
  render(
    <UndoToast
      cardName="Suspended Spell"
      instanceId="instance-2"
      onUndo={vi.fn()}
      onDismiss={onDismiss}
    />,
  );

  // Advancing from 5999 → 6000 ms: with the fix the first timer was
  // cleared and the new one has only 1 ms of its 6000 ms window.
  vi.advanceTimersByTime(1);
  expect(onDismiss).not.toHaveBeenCalled();

  // The new timer needs its full 6000 ms (5999 + 1):
  vi.advanceTimersByTime(5999);
  expect(onDismiss).not.toHaveBeenCalled();
  vi.advanceTimersByTime(1);
  expect(onDismiss).toHaveBeenCalledTimes(1);
});

